
import type { MoneyValueInput } from './MoneyValueInput.js';

export type PayoutInput = { "amount_money": MoneyValueInput; /** RFC3339 timestamp. Format: date-time. */ "arrival_at"?: never; "balance_source_type"?: "card" | "bank_account" | "fpx"; /** RFC3339 timestamp. Format: date-time. */ "created_at"?: never; /** ISO 4217 currency code. minLength: 3. maxLength: 3. pattern: ^[A-Z]{3}$. Example: "USD". */ "currency"?: never; "description"?: string; /** Caller-owned identifier for this resource in an external system. maxLength: 255. */ "external_reference_id"?: string; /** Flint-normalized payout failure code. Unknown provider values are returned as payout_failed. */ "failure_code"?: never; /** Flint-authored payout failure message. This is stable explanatory text, not a raw provider message. */ "failure_message"?: never; "fee_amount_status"?: never; "fee_money"?: never; /** Monetary amount represented as integer minor units plus an ISO 4217 currency code. */ "held_money"?: never; /** What started the payout. */ "initiated_by"?: never; "merchant_id"?: never; "metadata"?: Record<string, string>; "method": "standard"; "net_money"?: never; "original_payout"?: never; "original_payout_id"?: never; "payout_destination"?: never; "payout_destination_id"?: string; "payout_id"?: never; "reversal_status"?: never; "reversed_by_payout"?: never; "reversed_by_payout_id"?: never; "statement_descriptor"?: string; "status"?: never; "trace_id"?: never; /** RFC3339 timestamp. Format: date-time. */ "updated_at"?: never; };
